	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		var contenedor = this.Mapa;
		
		for (var i = 0; i < contenedor.numChildren; i++) {
		
		    var clip = contenedor.getChildAt(i);
		
		    clip.cursor = "pointer";
		
		    clip.addEventListener("click", function(evt){
		
		        evt.currentTarget.shape.graphics._fill.style = exportRoot.micolor.text;
		
		    });
		
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Capa_1
	this.Mapa = new lib.Símbolo371();
	this.Mapa.name = "Mapa";
	this.Mapa.setTransform(553.4,721.15,1,1,0,0,0,441.4,684.8);

	this.timeline.addTween(cjs.Tween.get(this.Mapa).wait(1));

